#!/bin/bash
# Remove files GENERATED by the sweep scripts; never the sources they derive from.
#
# Keeps (sources): Bowdoin_footprint_{run,init}_incmp_lumi.sif, meshextrushion.sif,
#   runresolution.sif + runresolution_<res>.sif, params.sif, *.sh, meshes, loads, *.F90/*.so.
# Removes (generated): params_<tag>.sif, run_<tag>.sif, init_<res>.sif, .sweep_locks/,
#   and ALWAYS the SaveLine _front*.dat -- note these sit in the Header "Results Directory"
#   (VTU_footprint_<res>[_A<area>]/), and are File Append so a rerun would double them;
#   and -- only with flags -- .bp / whole VTU dirs, logs, init results+markers, manifest.
#
#   bash clean_sweep.sh              # generated SIFs + front .dat + locks -- SAFE (keeps .bp/VTU)
#   bash clean_sweep.sh --outputs    # + .bp / VTU_footprint_* result files
#   bash clean_sweep.sh --logs       # + Logs/
#   bash clean_sweep.sh --init       # + footprint_bc_<res> init results + .init markers (forces re-init)
#   bash clean_sweep.sh --manifest   # + sweep_jobs.txt
#   bash clean_sweep.sh --all        # everything the scripts produced
#   bash clean_sweep.sh -n [flags]   # dry-run: list what WOULD be removed
#   RES=fine bash clean_sweep.sh ... # restrict to one resolution
#
# Tags come from `runelmer_multiple.sh --list`, so this always matches the current grid.
set -u

WORKER=${WORKER:-runelmer_multiple.sh}
RUN_SIF=${RUN_SIF:-Bowdoin_footprint_run_incmp_lumi.sif}

DRY=0; DO_OUT=0; DO_LOG=0; DO_INIT=0; DO_MAN=0
for a in "$@"; do case "$a" in
  -n|--dry-run) DRY=1 ;;
  --outputs)    DO_OUT=1 ;;
  --logs)       DO_LOG=1 ;;
  --init)       DO_INIT=1 ;;
  --manifest)   DO_MAN=1 ;;
  --all)        DO_OUT=1; DO_LOG=1; DO_INIT=1; DO_MAN=1 ;;
  *) echo "unknown option: $a"; exit 1 ;;
esac; done

# single-source the output naming from the template
NAME=$(sed -nE 's/^[[:space:]]*\$name[[:space:]]*=[[:space:]]*"([^"]+)".*/\1/p' "$RUN_SIF" | head -1)
RESTART=$(sed -nE 's/^[[:space:]]*\$restartfile[[:space:]]*=[[:space:]]*"([^"]+)".*/\1/p' "$RUN_SIF" | head -1)
: "${NAME:?could not read \$name from $RUN_SIF}"
: "${RESTART:?could not read \$restartfile from $RUN_SIF}"

rm_it () {                      # expand each pattern; remove (or list) existing matches
  local pat f
  for pat in "$@"; do
    for f in $pat; do
      [ -e "$f" ] || continue
      if (( DRY )); then echo "  [dry] $f"; else rm -rf "$f" && echo "  rm $f"; fi
    done
  done
}

echo "cleaning sweep artifacts (name=$NAME, restart=$RESTART)${RES:+, RES=$RES}$( ((DRY)) && echo ' [dry-run]')"

# ---- per-combo generated files (+ optional outputs) -----------------------
while read -r _idx res area p k; do
  [[ "$res" =~ ^(coarse|fine|superfine)$ ]] || continue
  tag="${res}_A${area}_p${p}_k${k}"
  rm_it "params_${tag}.sif" "run_${tag}.sif"
  # transient SaveLine .dat lives in the Header Results Directory: VTU_footprint_<res>_A<area>/.
  # Removed ALWAYS -- File Append would concatenate onto old data on a rerun.
  rm_it "VTU_footprint_${res}_A${area}/"*"_front"*".dat" \
        "${NAME}_${res}_A${area}_"*"_front"*".dat"     # CWD fallback if Results Directory unset
  (( DO_OUT )) && rm_it \
      "VTU_footprint_${res}_A${area}" \
      "${NAME}_${res}_A${area}_"*"-bulk.bp"            # CWD fallback
done < <(bash "$WORKER" --list)

# ---- per-resolution generated files (+ optional init results/markers) ------
for res in coarse fine superfine; do
  [[ -n "${RES:-}" && "$res" != "$RES" ]] && continue
  rm_it "init_${res}.sif"
  # init SaveLine .dat lives in its Results Directory VTU_footprint_<res>/ (no _A) -- also File Append
  rm_it "VTU_footprint_${res}/"*"_front"*".dat"
  (( DO_INIT )) && rm_it \
      "footprint_bc_${res}/${RESTART}.result."* \
      "footprint_bc_${res}/.init_${RESTART}.done" \
      "VTU_footprint_${res}"                           # whole init results dir (.bp etc.)
done

# ---- global generated artifacts -------------------------------------------
rm_it ".sweep_locks"
(( DO_LOG )) && rm_it "Logs"
(( DO_MAN )) && rm_it "sweep_jobs.txt"

echo "done."
